import assert from 'node:assert/strict';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { initializeInvoices, invoiceCollectionPlan, collectInvoices, correctInvoice } from '../../apps/worker/dist/invoices.js';
import { preparedPluginMailSource } from '../../apps/worker/dist/prepared-plugin-mail-source.js';
import { recordId } from '../../apps/worker/dist/invoice-model.js';
const account={email:'synthetic@example.test',label:'Synthetic'}, at=1793534400;
const path=join(process.env.FAMILYHUB_WORKER_DATA,'invoices.json');
const raw=id=>({id,threadId:'thread',internalDate:String(at*1000),labelIds:['INBOX'],payload:{mimeType:'text/plain',headers:[{name:'From',value:'billing@example.test'},{name:'Subject',value:'Receipt'}],body:{size:7,data:Buffer.from('CAD 40.').toString('base64url')}}});
const query=(request,ids=[],pages)=>({q:request.q,maxResults:request.maxResults,complete:true,pages:pages||[{messageIds:ids}]});
const sourceFor=(plan,ids=['aabbccdd'],pages)=>preparedPluginMailSource([{account,batch:{schema:1,account:account.email,messages:ids.map(raw),attachments:[],queries:[query(plan.incremental,ids,pages),...(plan.repair?[query(plan.repair.request)]:[]),...(plan.history?[query(plan.history.request)]:[])]}}]);
const classification={kind:'receipt',confidence:.97,transaction:true,reimbursement:'unknown',reason:'Synthetic',amount:40,currency:'CAD',category:'travel',member:'unknown',documentRole:'other',insurer:null,serviceDate:null,billedAmount:40,reimbursedAmount:null};
let count=0;
const forbidden=async()=>{throw new Error('Legacy credentials/network forbidden');};
const deps={credentials:forbidden,accessToken:forbidden,gmail:forbidden,classify:async()=>{count++;return {result:classification,source:'rules'};},historicalClassify:async()=>({result:classification,source:'rules'}),reviewer:async()=>{throw new Error('No external reviewer');},now:()=>new Date((at+3600)*1000)};
await initializeInvoices(true);
const first=invoiceCollectionPlan(account.email,at);
assert.equal((await readdir(process.env.FAMILYHUB_WORKER_DATA)).length,0);
assert.ok(Object.isFrozen(first));assert.ok(Object.isFrozen(first.window));
const stale=structuredClone(first);stale.at++;
await assert.rejects(collectInvoices({...deps,source:sourceFor(first),plans:[stale]}),/stale/);
await assert.rejects(collectInvoices({...deps,source:sourceFor(first)}),/plans/);
assert.equal((await readdir(process.env.FAMILYHUB_WORKER_DATA)).length,0);
let release,started;
const waiting=new Promise(resolve=>started=resolve), gate=new Promise(resolve=>release=resolve);
const run=collectInvoices({...deps,source:sourceFor(first),plans:[first],classify:async()=>{started();await gate;return deps.classify();}});
await waiting;
await assert.rejects(collectInvoices({...deps,source:sourceFor(first),plans:[first]}),/already running/);
release();await run;
let saved=JSON.parse(await readFile(path,'utf8'));
assert.equal(saved.accounts[account.email].through,at);assert.equal(saved.accounts[account.email].invoiceHistoryThrough,at);
assert.equal(saved.accounts[account.email].invoiceHistoryVersion,1);assert.equal(saved.accounts[account.email].healthReceiptRepairVersion,4);
assert.equal(saved.items.length,1);assert.equal(saved.items[0].SourceMessageId,'aabbccdd');assert.ok(saved.lastSuccess);
const preCorrection=invoiceCollectionPlan(account.email,at+7200);
await correctInvoice(recordId(account.email,'aabbccdd'),'marketing');
const before=await readFile(path,'utf8');
await assert.rejects(collectInvoices({...deps,source:sourceFor(preCorrection),plans:[preCorrection]}),/stale/);
assert.equal(await readFile(path,'utf8'),before);
const corrected=invoiceCollectionPlan(account.email,at+7200);
await collectInvoices({...deps,source:sourceFor(corrected),plans:[corrected]});
assert.equal(count,1);saved=JSON.parse(await readFile(path,'utf8'));assert.equal(saved.items[0].DocumentType,'marketing');
assert.equal(saved.items[0].Status,4);assert.equal(saved.items.length,1);
// Concurrent manual edits during asynchronous source preflight invalidate the plan without another write.
const racePlan=invoiceCollectionPlan(account.email,at+9000),raceGood=sourceFor(racePlan);let afterRaceCorrection;
const raceSource={...raceGood,preflight:async(account,paths)=>{await raceGood.preflight(account,paths);await correctInvoice(recordId(account.email,'aabbccdd'),'marketing');afterRaceCorrection=await readFile(path,'utf8');}};
await assert.rejects(collectInvoices({...deps,source:raceSource,plans:[racePlan]}),/changed before application/);
assert.equal(await readFile(path,'utf8'),afterRaceCorrection);
// A runtime transport failure cannot advance the frozen window or erase last good coverage.
const failurePlan=invoiceCollectionPlan(account.email,at+10800), good=sourceFor(failurePlan,['eeff0011']);
const broken={...good,open:async account=>{const session=await good.open(account);return {read:async path=>{if(path.includes('/eeff0011?'))throw new Error('Synthetic failed source');return session.read(path);}};}};
await collectInvoices({...deps,source:broken,plans:[failurePlan]});
saved=JSON.parse(await readFile(path,'utf8'));assert.equal(saved.accounts[account.email].through,at+7200);assert.equal(saved.accounts[account.email].window.before,at+10800);assert.match(saved.accounts[account.email].error,/Synthetic/);assert.equal(saved.items.length,1);
// Complete plugin evidence may exceed the two-page processing budget; its cursor resumes only through the plugin.
const partial=invoiceCollectionPlan(account.email,at+14400);
const pages=[{messageIds:[],nextPageToken:'plugin2'},{pageToken:'plugin2',messageIds:[],nextPageToken:'plugin3'},{pageToken:'plugin3',messageIds:[]}];
await collectInvoices({...deps,source:sourceFor(partial,[],pages),plans:[partial]});
saved=JSON.parse(await readFile(path,'utf8'));assert.equal(saved.accounts[account.email].window.page,'plugin3');assert.equal(saved.accounts[account.email].through,at+7200);
const resume=invoiceCollectionPlan(account.email,at+14400);await collectInvoices({...deps,source:sourceFor(resume,[],pages),plans:[resume]});
saved=JSON.parse(await readFile(path,'utf8'));assert.equal(saved.accounts[account.email].window,undefined);assert.equal(saved.accounts[account.email].through,at+10800);
// Explicit no-cursor rollback clears plugin provenance before creating/resuming legacy pagination.
const manualBeforeRollback=JSON.stringify(saved.items);
let legacyCalls=[];
const legacy={...deps,now:()=>new Date((at+20000)*1000),credentials:async()=>({accounts:[{...account,clientId:'synthetic',clientSecret:'synthetic',refreshToken:'synthetic'}]}),accessToken:async()=> 'synthetic',gmail:async(_token,path)=>{const page=new URL(path,'https://synthetic.invalid/').searchParams.get('pageToken');legacyCalls.push(page);return page==='legacy3'?{messages:[]}:{messages:[],nextPageToken:page==='legacy2'?'legacy3':'legacy2'};}};
await collectInvoices(legacy);saved=JSON.parse(await readFile(path,'utf8'));
assert.equal(saved.accounts[account.email].transport,undefined);assert.equal(saved.accounts[account.email].window.page,'legacy3');
assert.equal(JSON.stringify(saved.items),manualBeforeRollback);
await collectInvoices(legacy);saved=JSON.parse(await readFile(path,'utf8'));
assert.deepEqual(legacyCalls,[null,'legacy2','legacy3']);assert.equal(saved.accounts[account.email].window,undefined);assert.equal(saved.accounts[account.email].through,at+20000);assert.equal(saved.accounts[account.email].transport,undefined);
assert.equal(JSON.stringify(saved.items),manualBeforeRollback);
// Unnamed binary originals stay exact source assets, not invented invoice attachment rows.
const unnamedPlan=invoiceCollectionPlan(account.email,at+21000),unnamedId='f00d1234',original=Buffer.from([137,80,78,71,13,10,26,10]),unnamed=raw(unnamedId);
unnamed.payload={mimeType:'multipart/related',filename:'',headers:unnamed.payload.headers,body:{size:0},parts:[{...unnamed.payload,headers:[]},{mimeType:'image/png',filename:'',headers:[],body:{size:original.length,attachmentId:'unnamed_original'}}]};
const unnamedSource=preparedPluginMailSource([{account,batch:{schema:1,account:account.email,messages:[unnamed],attachments:[{messageId:unnamedId,attachmentId:'unnamed_original',size:original.length,data:original.toString('base64url')}],queries:[query(unnamedPlan.incremental,[unnamedId])]}}]);
await collectInvoices({...deps,source:unnamedSource,plans:[unnamedPlan]});saved=JSON.parse(await readFile(path,'utf8'));
assert.deepEqual(saved.items.find(item=>item.SourceMessageId===unnamedId).Attachments,[]);assert.equal(JSON.stringify(saved.items.filter(item=>item.SourceMessageId!==unnamedId)),manualBeforeRollback);
// A cursor without plugin provenance is not assumed compatible.
saved.accounts[account.email].window={after:at,before:at+18000,page:'oauth'};delete saved.accounts[account.email].transport;
await writeFile(path,JSON.stringify(saved));await initializeInvoices(true);
const foreign=invoiceCollectionPlan(account.email,at+18000), foreignBefore=await readFile(path,'utf8');
const foreignPages=[{messageIds:[],nextPageToken:'oauth'},{pageToken:'oauth',messageIds:[]}];
await assert.rejects(collectInvoices({...deps,source:sourceFor(foreign,[],foreignPages),plans:[foreign]}),/another transport/);
assert.equal(await readFile(path,'utf8'),foreignBefore);
console.log('Prepared invoice plans, no-secret source, frozen clock, concurrency, manual authority, failure and cursor resume passed.');
